from src.main import PREMISSAS, rodar

DADOS = Path(__file__).resolve().parents[1] / "data" / "raw" / "set2026"
ATLAS = "1076801732"
DE_PARA_R3 = {"1043300981": "66564512000199", "1043396662": "78576234000179", "1038867654": "07752116000126"}


