    vigentes = {id(lt) for lt in self.linhas_vigentes(cnpj, dia)}
    return {
        lt.taxas[chave] for lt in self.linhas
        if lt.cnpj == cnpj and id(lt) not in vigentes and lt.taxas.get(chave) is not None
    }

