CASA, ROTA, BRIDGE = "00520815000100", "95927868000148", "22224579000109"


@pytest.fixture(scope="module")
def res():
    return rodar(DADOS)


@pytest.fixture(scope="module")
def saida(res, tmp_path_factory):
    pasta = tmp_path_factory.mktemp("saida")
    escrever(res, pasta)
    return pasta


def _csv(pasta, nome):
    with (pasta / nome).open(encoding="utf-8", newline="") as f:
        return list(csv.DictReader(f, delimiter=";"))


# --- Seção 5: aceitação de setembro (valores pela R8) ---

def test_setembro_totais(res):
    assert len(res.divergencias) == 210
    assert sum(d.diferenca_brl for d in res.divergencias) == Decimal("16973.65")
    assert not [d for d in res.divergencias if d.causa == "NAO_DETERMINADA"]


@pytest.mark.parametrize("cnpj, causa, n, taxa, total", [
    (CASA, "ISENCAO_IGNORADA", 118, "15397.42", "15396.77"),
    (ROTA, "DEGRAU_SISTEMICO", 87, "1546.28", "1545.56"),
    (BRIDGE, "TAXA_OUTRA_VIGENCIA", 5, "29.95", "29.44"),
])
def test_setembro_por_cnpj(res, cnpj, causa, n, taxa, total):
    x = res.leituras_cnpj[cnpj]
    assert (x.situacao, x.linhas_divergentes) == (causa, n)
    assert x.diferenca_taxa_brl == Decimal(taxa)
    assert x.diferenca_total_brl == Decimal(total)


def test_setembro_rota_degrau_nos_tres_creditos(res):
    x = res.leituras_cnpj[ROTA]
    assert (x.modalidades_afetadas, x.desvio_pp) == ("CREDITO_2_6,CREDITO_7_12,CREDITO_VISTA", "+0.50")
    assert x.periodo_inicio == date(2026, 9, 12)


def test_setembro_bridge_vigencia(res):
    ds = [d for d in res.divergencias if d.cnpj == BRIDGE]
    assert {(d.taxa_contratada_pct, d.taxa_aplicada_pct) for d in ds} == {(Decimal("2.19"), Decimal("2.59"))}
    assert (min(d.data_ref for d in ds), max(d.data_ref for d in ds)) == (date(2026, 9, 15), date(2026, 9, 18))


def test_setembro_demais_so_truncamento(res):
    outros = {k: v for k, v in res.leituras_cnpj.items() if k not in (CASA, ROTA, BRIDGE)}
    assert len(outros) == 18
    assert all(v.situacao == "SO_TRUNCAMENTO" and v.diferenca_taxa_brl == 0 for v in outros.values())
    truncamentos = [v.diferenca_truncamento_brl for v in outros.values()]
    assert (min(truncamentos), max(truncamentos)) == (Decimal("-0.71"), Decimal("-0.22"))


def test_degrau_vem_antes_da_correspondencia_exata(res):
    """H5/M7: 2,49 + 0,50 = 2,99 é a taxa do 2-6x da Rota. Sem o degrau, a venda à vista viraria OUTRA_FAIXA."""
    cad = Cadastro(rodar.__globals__["ler_taxas"](DADOS / "02_tabela_taxas_contratadas.xlsx"),
                   rodar.__globals__["json"].loads(rodar.__globals__["PREMISSAS"].read_text(encoding="utf-8")))
    vista = [c for c in res.calculadas if c.cnpj == ROTA and c.produto == "CREDITO_VISTA"
             and c.linha.taxa_aplicada_pct == Decimal("2.99")]
    assert vista and all(_causa(c, cad, {})[0] == "OUTRA_FAIXA_PARCELAS" for c in vista)
    ids = {c.linha.id_transacao for c in vista}
    assert {d.causa for d in res.divergencias if d.ref_origem in ids} == {"DEGRAU_SISTEMICO"}


def test_duas_explicacoes_viram_nao_determinada_sem_escolher():
    taxas = {"DEBITO": Decimal("0.0089"), "CREDITO_VISTA": Decimal("0.0249"), "CREDITO_2_6": Decimal("0.0299"),
             "CREDITO_7_12": Decimal("0.0359"), "PIX": Decimal("0.0089"), "ANTECIPACAO": Decimal("0.021")}
    lt = LinhaTaxa(6, "Teste Ltda", "11111111000111", "999", taxas, (date(2026, 1, 1), None), "")
    cad = Cadastro([lt], {"de_para_ec": {}, "isencoes": []})
    linha = LinhaOrbe(2, "TX1", date(2026, 9, 10), "999", "TESTE", "VENDA", "CREDITO A VISTA", 1,
                      Decimal("100"), Decimal("0.89"), Decimal("0.89"), Decimal("99.11"), "", None)
    c = LinhaCalc(linha, "11111111000111", "CREDITO_VISTA", date(2026, 9, 10), taxas["CREDITO_VISTA"], None,
                  Decimal("2.49"))
    causa, _, candidatas = _causa(c, cad, {})
    assert causa == "NAO_DETERMINADA"
    assert len(candidatas) == 2 and all(x.startswith("MODALIDADE_TROCADA") for x in candidatas)


# --- Seção 8.2: fatos dos dados ---

def test_taxa_em_texto_e_em_fracao():
    assert taxa_planilha("1,49%") == taxa_planilha(0.0149) == Decimal("0.0149")
    assert taxa_planilha("padrão") is None


def test_bridge_duas_vigencias():
    import json
    from src.leitura import ler_taxas
    premissas = json.loads((Path(__file__).resolve().parents[1] / "src" / "premissas.json").read_text("utf-8"))
    cad = Cadastro(ler_taxas(DADOS / "02_tabela_taxas_contratadas.xlsx"), premissas)
    assert cad.taxa(BRIDGE, "CREDITO_VISTA", date(2026, 9, 14))[0] == Decimal("0.0259")
    assert cad.taxa(BRIDGE, "CREDITO_VISTA", date(2026, 9, 15))[0] == Decimal("0.0219")


def test_estorno_de_agosto_usa_taxa_da_venda(res):
    c = next(c for c in res.calculadas if c.linha.id_transacao == "TX88445133")
    assert c.data_ref == date(2026, 8, 21) and c.isencao is None
    assert c.taxa_contratada == Decimal("0.0149")
    assert "TX88445133" not in {d.ref_origem for d in res.divergencias}


# --- Seção 6: validações obrigatórias ---

def test_v1_grupos_somam_as_linhas(res, saida):
    linhas = sum(Decimal(r["diferenca_brl"]) for r in _csv(saida, "divergencias_taxa.csv"))
    grupos = sum(Decimal(r["diferenca_brl"]) for r in _csv(saida, "divergencias_grupos.csv"))
    assert linhas == grupos == sum(d.diferenca_brl for d in res.divergencias)


def test_v2_causas_por_cnpj_fecham(saida):
    for r in _csv(saida, "comissoes_por_lojista.csv"):
        valores = [Decimal(v) for v in re.findall(r"R\$ (-?\d+\.\d{2})\)", r["causas"])]
        assert sum(valores, Decimal("0")) == Decimal(r["diferenca_taxa_brl"]), r["cnpj"]
        assert (Decimal(r["diferenca_taxa_brl"]) + Decimal(r["diferenca_truncamento_brl"])
                == Decimal(r["diferenca_total_brl"])), r["cnpj"]


def test_v3_rastro_soma_por_id_saida(res, saida):
    soma = defaultdict(Decimal)
    for r in _csv(saida, "rastro.csv"):
        soma[r["id_saida"]] += Decimal(r["valor"])
    reportado = {}
    for arquivo, coluna in (("comissoes_por_lojista.csv", "comissao_brl"), ("pendencias.csv", "valor_brl"),
                            ("divergencias_taxa.csv", "diferenca_brl"), ("divergencias_grupos.csv", "diferenca_brl")):
        for r in _csv(saida, arquivo):
            reportado[r["id_saida"]] = Decimal(r[coluna])
    assert {k: soma[k] for k in reportado} == reportado


def test_v4_toda_divergente_tem_causa_e_sem_cadastro_nao_entra(res):
    divergentes = {c.linha.id_transacao for c in res.calculadas
                   if c.linha.taxa_aplicada_pct != c.taxa_contratada * 100}
    assert divergentes == {d.ref_origem for d in res.divergencias}
    pend = {p.ref_origem for p in res.pendencias}
    assert all(d.causa != "NAO_DETERMINADA" or d.ref_origem in pend for d in res.divergencias)
    sem_cadastro = {r.ref_origem for r in res.rastro if r.id_saida.startswith(("PEND-EC-", "PEND-TX-"))}
    assert not sem_cadastro & {d.ref_origem for d in res.divergencias}


def test_v5_nenhum_campo_com_ponto_e_virgula_ou_quebra(saida):
    for arquivo in saida.glob("*.csv"):
        with arquivo.open(encoding="utf-8", newline="") as f:
            linhas = list(csv.reader(f, delimiter=";"))
        assert len({len(linha) for linha in linhas}) == 1, arquivo.name
        for linha in linhas:
            assert not any(";" in campo or "\n" in campo or "\r" in campo for campo in linha), arquivo.name


def _numeros(texto: str) -> tuple[set[Decimal], set[date]]:
    datas = {date(int(a), int(m), int(d)) for d, m, a in re.findall(r"(\d{2})/(\d{2})/(\d{4})", texto)}
    datas |= {date.fromisoformat(x) for x in re.findall(r"\d{4}-\d{2}-\d{2}", texto)}
    texto = re.sub(r"\d{2}/\d{2}/\d{4}|\d{4}-\d{2}-\d{2}|\b[A-Z][A-Z0-9_]*\b", " ", texto)
    nums = set()
    for tok in re.findall(r"[+-]?\d{1,3}(?:\.\d{3})+,\d+|[+-]?\d+(?:[.,]\d+)?", texto):
        nums.add(Decimal(tok.replace(".", "").replace(",", ".") if "," in tok else tok))
    return nums, datas


def _permitidos(valores) -> set[Decimal]:
    out = set()
    for v in valores:
        out |= {Decimal(str(v)), abs(Decimal(str(v)))}
    return out


def test_v6_texto_so_usa_numeros_da_linha(saida):
    grupos = _csv(saida, "divergencias_grupos.csv")
    por_cnpj = defaultdict(lambda: (set(), set()))
    for g in grupos:
        nums = _permitidos([g[k] for k in ("taxa_contratada_pct", "taxa_aplicada_pct", "desvio_pp",
                                           "n_transacoes", "diferenca_brl")])
        datas = {date.fromisoformat(g["janela_inicio"]), date.fromisoformat(g["janela_fim"])}
        achados, achadas = _numeros(g["leitura_causa"] + " " + g["detalhe"])
        assert achados <= nums, (g["id_saida"], achados - nums)
        assert achadas <= datas, (g["id_saida"], achadas - datas)
        por_cnpj[g["cnpj"]][0].update(nums)
        por_cnpj[g["cnpj"]][1].update(datas)
    for r in _csv(saida, "comissoes_por_lojista.csv"):
        nums = por_cnpj[r["cnpj"]][0] | _permitidos([r["qtd_transacoes"], r["diferenca_total_brl"]])
        achados, achadas = _numeros(r["leitura_causa"])
        assert achados <= nums, (r["cnpj"], achados - nums)
        assert achadas <= por_cnpj[r["cnpj"]][1], r["cnpj"]


def test_v7_determinismo(tmp_path):
    a, b = tmp_path / "a", tmp_path / "b"
    escrever(rodar(DADOS), a)
    escrever(rodar(DADOS), b)
    for arquivo in sorted(a.iterdir()):
        assert arquivo.read_bytes() == (b / arquivo.name).read_bytes(), arquivo.name

